-- changed.
UPDATE routes SET watch_out = '["PG13 rating indicates moderate hazard concerns and moderate protection", "Glacier approach with exposure on final sections", "4th class rock scrambling with falling rock potential"]'::jsonb WHERE id = 'wa_sahale_mountain_r1';
-- dist_km corrected 16.9 -> 8.37: the app renders round trip as dist_km*2 (one-way convention),
-- but 16.9km = 10.5mi already equals the ROUND TRIP mileage this row's own itinerary.totalNote
-- states ('roughly 10.5 mi and 5,500 ft of gain'), and matches the row's own waypoints, whose
-- cumulative summit distMi is 5.2mi one-way (5.2*2=10.4mi, matching totalNote almost exactly).
-- Corrected value is that one-way 5.2mi expressed in km (5.2*1.609344=8.37); doubled for
-- display it now reproduces the round-trip mileage the row already states elsewhere, instead
