UPDATE routes SET dist_km = 8.37 WHERE id = 'wa_sahale_mountain_r1';

-- Sahale Mountain, Sahale Arm / Sahale Glacier (wa_sahale_mountain_sahale_glacier):
-- gain_ft corrected 5020 -> 5080: this route is a true round trip returning to the same
-- Cascade Pass Trailhead it starts from (descent_text: 'descent is simply a reverse of the
-- Sahale Arm and Cascade Pass trails back to the trailhead'), so gain_ft must equal loss_ft
-- (already 5080). The row's own waypoints (trailhead 3,600ft, summit 8,680ft) independently
-- give the same 5,080ft round-trip figure. itinerary.days[0].gainFt (3940) and
-- days[1].lossFt (5020) shared the identical 60ft undercount against the waypoint chain --
-- both corrected to 4000/5080 (trailhead-to-camp = 7600-3600=4000, matching the already-
-- correct camp-to-summit gain of 1080 elsewhere on the same row), and the day 2 schedule's
-- '3,940 ft down' note updated to match. totalNote's '~5,000 ft gain' still rounds correctly
-- either way and was left as is.
UPDATE routes SET gain_ft = 5080 WHERE id = 'wa_sahale_mountain_sahale_glacier';
UPDATE routes SET itinerary = '{"cal": "Sahale Glacier Camp is one of the most sought-after permits in North Cascades NP; get an early-access wilderness permit or a walk-up the day before at the Marblemount ranger station.", "days": [{"gainFt": 4000, "hours": 4.5, "lossFt": 0, "miles": 5.9, "n": 1, "note": "From the Cascade Pass Trailhead, switchback up to Cascade Pass (3.7 mi, ~1,800 ft), then continue up the Sahale Arm climbers'' trail to the permitted camp at ~7,600 ft. The final 0.6-0.7 mi above the Arm is loose scree/talus on cairns with real exposure \u2014 go slow and watch weather.", "objective": "Reach Sahale Glacier Camp", "packLb": 35, "schedule": [], "title": "Approach to Sahale Glacier Camp"}, {"gainFt": 1080, "hours": 10, "lossFt": 5080, "miles": 7.3, "n": 2, "note": "An early start to cross the small, crevassed Sahale Glacier while snow is firm, then a class 2-3 scramble to the 8,680 ft summit. Most parties return to camp, break it down, and hike all the way out to the car the same day rather than spend a second night.", "objective": "Climb Sahale Mountain via the Sahale Glacier, then descend to the trailhead", "packLb": 35, "schedule": [{"detail": "Crampons/axe (and rope for glacier travel) go on before leaving camp.", "label": "Rope up and gear up at camp", "time": "4:30 AM"}, {"detail": "Firm morning snow makes crevasse crossing safer and faster.", "label": "Leave camp, cross the Sahale Glacier", "time": "5:00 AM"}, {"detail": "Loose rock near the top; some parties place a hand line.", "label": "Class 2-3 scramble to the summit block", "time": "+2 hr"}, {"detail": "Views over Boston Basin and the Ptarmigan Traverse peaks.", "label": "Summit (8,680 ft)", "time": "~9:00 AM"}, {"detail": "Pack up the tent and overnight gear for the descent.", "label": "Back at camp, break it down", "time": "~11:00 AM"}, {"detail": "5.9 mi / 4,000 ft down; most parties reach the trailhead by late afternoon.", "label": "Descend Sahale Arm and Cascade Pass trail", "time": "12:00 PM"}], "title": "Summit push and hike out"}], "totalNote": "A popular 1-night backpack: ~13 mi round trip and ~5,000 ft gain, with an alpine-start glacier crossing and summit scramble on day 2 before hiking all the way out."}'::jsonb WHERE id = 'wa_sahale_mountain_sahale_glacier';

