UPDATE routes SET itinerary = '{"cal": "", "totalNote": "Typically a single long day trip from Longmire: trailhead to the Eagle Peak-Chutla saddle (~3.6 mi one-way, ~2,900 ft gain), saddle to summit via the ridge scramble (short distance, roughly 250-300 ft of additional gain over uneven terrain), then reverse the full route to the trailhead \u2014 on the order of 7-9 miles and ~3,200 ft round trip depending on the exact line taken through the summit scramble.", "days": []}'::jsonb WHERE id = 'wa_scramble_route';
