-- Mount Washington (Olympics), SE Ridge AKA Shield Wall (wa_se_ridge_aka_shield_wall):
-- detailed_rack converted from a stringified JSON-array literal (literal brackets/quotes)
-- back to the plain prose string every other route in the catalog uses for this column --
-- no content changed, only the four bracketed/quoted array items joined into one sentence.
UPDATE routes SET detailed_rack = 'Single alpine rack: cams roughly #0.3-#3; set of stoppers/wires (~sizes 4-10); alpine draws and extra shoulder slings (few horns/blocks to sling on this route); 60m rope minimum recommended, some parties prefer a 40m lead line plus a separate 30m rappel line.' WHERE id = 'wa_se_ridge_aka_shield_wall';
-- loss_ft filled in (was null) to match gain_ft (3229): this route's own descent_text says the
-- standard descent reverses via Mount Washington's scramble route back to 'the same FR-2419/Big
