-- bivy pruned 8->2, removing six entries (Lena Lake designated sites, The Brothers climbers
-- camp/Valley of the Silent Men, Upper Lena Lake, Lake of the Angels, Hamma Hamma River road
-- campgrounds, and Jefferson Creek roadside pull-outs) that are explicitly and solely for other
-- Hamma Hamma-corridor peaks (The Brothers, Mount Stone, Mount Skokomish via the Putvin trail,
-- Mount Pershing) reached from a different road/trailhead system than this route's own FR-2419/
-- Lake Cushman corridor. Kept Big Creek Campground, Lake Cushman ('the obvious roadside base for
-- MOUNT ELLINOR AND MOUNT WASHINGTON') and Staircase Campground ('further from the Ellinor and
-- Washington trailheads than Big Creek'), both of which name this peak directly.
UPDATE routes SET bivy = '[{"capacity": "A large forested loop campground \u2014 published site counts vary between roughly two dozen and considerably more, so check current numbers rather than trusting a figure. Sites are well spaced in second growth", "elev": 920, "name": "Big Creek Campground, Lake Cushman", "notes": "The obvious roadside base for MOUNT ELLINOR AND MOUNT WASHINGTON, sitting at the junction where the Lake Cushman road becomes FR 24, with FR 2419 climbing from there to the Ellinor lower trailhead at about 2,600 ft, the upper trailhead at about 3,500 ft, and the Mount Washington trailhead at the road end near 3,000 ft. Both peaks are genuine day objectives \u2014 Ellinor is a maintained trail and Washington a class 3 scramble through a basin and gully \u2014 so this is EXPLICITLY A CONTINGENCY RATHER THAN THE NORMAL PLAN: it exists for the party that arrives the night before to get an early start on a hot day, or that comes down from the Washington gully later than intended and would rather not drive. It is also the sane base for anyone linking the Washington\u2013Ellinor ridge traverse, which takes far longer than either peak alone. A trail from the campground connects up toward the Mount Ellinor system if you want to walk the whole thing from the tent, but that turns a half-day into a very long one.", "permit": "Per-night Forest Service fee. No wilderness permit \u2014 this is a developed campground on Forest Service land, outside the national park. Vault toilets, tables and fire rings, pack it in and pack it out. Note the separate parking rule up the hill: a NORTHWEST FOREST PASS IS REQUIRED AT THE MOUNT ELLINOR UPPER TRAILHEAD BUT NOT AT THE LOWER ONE, and the Mount Washington trailhead at the end of FR 2419 follows the Forest Service pass regime as well", "type": "camp", "water": "Seasonal potable water is generally available in the campground, but do not count on it outside the main summer season. Big Creek runs alongside"}, {"capacity": "Around 49 sites along the river, some reservable in high summer and the rest first come, first served", "elev": 800, "name": "Staircase Campground, North Fork Skokomish", "notes": "The park-side alternative at the head of Lake Cushman, a few miles beyond Big Creek. For the climbing in this zone it is a SECOND-CHOICE CONTINGENCY rather than a plan: it is further from the Ellinor and Washington trailheads than Big Creek, it costs more because of the park entrance fee, and the road in is less dependable. It earns its place for two reasons. It is the entry area named on the permit for Upper Lena Lake, so a party collecting or sorting out a park wilderness permit may already be dealing with this side of the boundary. And it is the fallback with real amenities when the Forest Service campgrounds below Ellinor are full on a summer weekend, which they routinely are. Worth knowing that the developed area has had extended seasonal closures in recent years, so confirm it is open before committing to the drive.", "permit": "Olympic National Park entrance fee applies, plus a per-night campground fee. Reservations through Recreation.gov are used for the peak midsummer window and the campground reverts to first come, first served either side of it; it runs primitive with reduced services through the winter. NO WILDERNESS PERMIT IS NEEDED FOR THE CAMPGROUND ITSELF \u2014 that is only for backcountry nights. Standard park food storage rules apply. Access is by the unpaved FR 24 beyond Lake Cushman, which closes in bad weather and is frequently shut through the winter and spring", "type": "camp", "water": "Potable water in season; the North Fork Skokomish runs through the campground"}]'::jsonb WHERE id = 'wa_se_ridge_aka_shield_wall';

-- Sentinel Peak, Standard Route (wa_sentinel_peak_standard):
-- seasonal_guidance.optimalWindow was truncated mid-sentence ('...consistent with '); trimmed
-- to the complete clause rather than inventing what it was originally consistent with.
UPDATE routes SET seasonal_guidance = '{"monthBreakdown": {"August": {"reason": "Most stable glacier travel and driest rock conditions of the season; core of the best-season window", "status": "optimal"}, "July": {"reason": "Route becomes viable as snow recedes, matching the best-season start, but early July can still carry more residual snow/soft glacier bridges than late summer", "status": "good"}, "June": {"reason": "Lingering snowpack over approach terrain and creek crossings; glacier travel and moat conditions less predictable, and this early in the season access to the Ptarmigan Traverse trailheads/passes may still be snow-choked", "status": "risky"}, "October": {"reason": "Outside the best-season window; shortening days, higher storm/new-snow probability, and increased difficulty on the long remote approach", "status": "risky"}, "September": {"reason": "Generally stable weather and good climbing conditions, though glacier crevasses are more open/thinning late in the month and early-season storms can arrive by month''s end", "status": "optimal"}}, "optimalWindow": "Late July through early September."}'::jsonb WHERE id = 'wa_sentinel_peak_standard';
-- bivy[0] (Cache Col and the Cache Glacier shoulder) elev corrected 6400 -> 6900: this row's own
-- prior correction (logged 2026-07-31) already fixed the approach text's Cache Col elevation to
-- 6,900 ft to match Wikipedia and this row's own waypoint, but the bivy entry for the same named
-- col was not updated in that same pass and was left at the old 6,400 ft.
UPDATE routes SET bivy = '[{"capacity": "Snow platforms and a few rock benches on the shoulder below and at the col, room for one or two parties. Nothing built, no toilet, no windbreaks worth the name.", "elev": 6900, "name": "Cache Col and the Cache Glacier shoulder", "notes": "The col is the gateway to everything here. From the Cascade Pass trail a boot path climbs south along the arm and onto the mellow Cache Glacier, which is corniced at the col early in the season and can need a careful step through. Parties who leave the car in the afternoon and lose the light on the climb sometimes stop here rather than commit to the awkward descending traverse beyond it, and parties coming back north at the end of a trip do the same. It is a fair-weather choice only: it is a high, open saddle with no shelter and no water, and in cloud the ground on both sides is easy to lose. Treat the elevation as approximate, since published figures for the col vary by a couple of hundred feet.", "permit": "THIS IS THE LAST GROUND ON THE PARK SIDE, and the distinction decides which permit you need. A night at or above the col is inside North Cascades National Park and requires an NPS wilderness permit for the relevant cross-country zone, collected in person at the Marblemount Wilderness Information Center, with part of the inventory reservable in advance and part held for walk-ups. Approved bear-resistant food storage applies. One step south of the col you are in Glacier Peak Wilderness and a free self-issue register slip is all that is needed. Do not assume the wilderness self-issue covers a night at the col.", "type": "bivy", "water": "None at the col itself. Early in the season there are melt runnels on the shoulder below it; by August there is usually nothing, and parties either carry up from the Cascade Pass side or melt snow. This is the single most common reason people push on down to the tarn below instead of stopping here."}, {"capacity": "A small number of party-sized spots split between the west notch of the col and the ground above the east pass, on glacial slabs and snow. Two parties is comfortable, three is crowded, and there is no toilet.", "name": "Spider-Formidable Col", "notes": "THE WORKING BASE CAMP FOR BOTH SPIDER MOUNTAIN AND MOUNT FORMIDABLE, and the reason to know about it is that a party climbing either peak stops here while a party walking the traverse does not. The twin notches of the col divide the two mountains, and it is reached by crossing the upper Middle Cascade Glacier almost due south from the Red Ledge. Spider Mountain is climbed from here by its south gully, stepping onto the buttress to the east and finishing along a corniced east ridge, about nineteen miles round trip from the Cascade Pass trailhead. Formidable is the other direction, and its south scramble is only class 3 but is long, loose, exposed and hard to route-find, with a fatality on record; the same ground is the only practical descent. Published elevations for the col disagree badly, with figures from roughly 6,600 to 7,400 feet, so no number is recorded here rather than pick one. The descent off the south side toward Yang Yang can be very steep snow and parties have resorted to a hand line anchored on buried pickets.", "permit": "Glacier Peak Wilderness, free self-issue permit from the register at whichever trailhead you started from. Camp on snow, rock or bare slab rather than on the heather. Pack out human waste; there is no toilet anywhere south of Cache Col. Stoves only.", "type": "bivy", "water": "Water trickles off the slabs beside the col through most of the climbing season, which is unusual for ground this high and is the main reason the col gets used as a base rather than just crossed. It is meltwater, so it weakens through August and can stop entirely in a light snow year, and there is nothing else until the lakes well below on either side."}, {"capacity": "Open alpine benches with room for a party or two, on heather and rock. Unimproved, no toilet, no windbreaks.", "elev": 7100, "name": "Drop Creek high camp", "notes": "THIS IS THE OTHER WAY TO FORMIDABLE AND IT IS NOT THE TRAVERSE. It starts at the South Fork Cascade River trailhead, which is little more than a bend in the Cascade River Road around mile 17 to 18 near the Forest Service 1590 junction, well below the road end at Cascade Pass. The first mile is maintained, then the trail deteriorates into ups, downs and overgrown nettle sections; past the Middle Fork turnoff you cross Drop Creek on a log and turn up into its valley on a climbers'' path. That path fades after a few hundred vertical feet, but the forest above about 4,000 feet is open and the bushwhacking is unusually easy for this part of the range, with one short slide alder thicket below 4,600 feet. The camp is the obvious flat ground at around 7,100 feet with water, and from it the ground steepens to class 3 with a permanent snowfield near 7,400 feet and one narrow chasm crossing that is worth protecting. The whole approach avoids glacier travel entirely, which is why it has become the late-season choice, and recent trail work has made it the most pleasant it has been in years. Reckon on roughly twenty-five miles and eight thousand feet for the round trip.", "permit": "Glacier Peak Wilderness on Mount Baker-Snoqualmie National Forest, free self-issue wilderness permit at the trailhead register. A Northwest Forest Pass or Interagency pass is the usual requirement for the vehicle at Forest Service trailheads on this road, unlike the park trailhead at the end of it, so check before leaving the car. No fires at this elevation.", "type": "camp", "water": "Running water beside the camp for most of the season, fed by the snowfield above, and a second reliable source lower down around 5,600 feet before the steep meadow climb. Late in a dry summer take the lower water seriously, because the high source is a snowfield that is shrinking."}, {"capacity": "Rough forest sites along the valley trail and near the Drop Creek crossing, party-sized only. Nothing established.", "name": "South Fork Cascade River valley camps", "notes": "The fallback first night on the Drop Creek approach to Formidable, for a party that starts late or is not confident of reaching the high camp in one push. It exists because the valley section is slower than its mileage suggests once the maintained tread runs out, with overgrown stretches and repeated small gains and losses. Camping here costs you the high camp''s position and its view, and it means carrying the whole climb the next day, so most parties push through; it is recorded because the alternative to knowing it is there is a headlamp bushwhack up Drop Creek. No elevation is given because no confident figure was found for the usual sites.", "permit": "Glacier Peak Wilderness self-issue permit; Northwest Forest Pass or Interagency pass on the vehicle at the Forest Service trailhead. This is the one part of the zone low enough that a fire is not automatically out of the question, but it is damp valley forest and a stove is the sensible choice.", "type": "camp", "water": "The South Fork and Drop Creek itself, running all season. Water is never the problem down here; the log crossing in high water can be."}, {"capacity": "Heather and gravel benches around the pass and its tarns, enough for two or three parties spread out. Unimproved, no toilet.", "elev": 6800, "name": "Le Conte Pass", "notes": "The pass sits on the shoulder above the lakes in the basin below Le Conte Mountain, and it is the direct base for Le Conte itself, which is climbed by working up its east slope on talus and blocky rock by the line of least resistance rather than by any single defined route. It is also where parties running late stop instead of dropping into and re-climbing out of the steep basin below, which is the trade that decides most itineraries on this stretch: better position and worse water, against reliable water and a thousand feet of extra work. From the pass the next day crosses the Le Conte Glacier, which is the most broken ice on this part of the crest and has turned parties around outright, so this is a camp to leave early and roped. Published elevations for the pass vary, so treat the figure as approximate.", "permit": "Glacier Peak Wilderness, free self-issue permit. Keep camps back from the tarns, camp on snow, rock or bare ground rather than on the heather, and pack out human waste. Stoves only.", "type": "bivy", "water": "Small tarns at the pass hold water through midsummer and are the practical source, but they are snowmelt pools with tiny catchments and they can be gone or foul by September. Late in the season this is a dry camp and the lakes below are the honest answer."}, {"capacity": "Snow platforms and small rock benches at each of the two saddles, one party at a time at either. Nothing built, no toilet, nothing sheltered.", "name": "Sentinel Pass and Lizard Col", "notes": "The two saddles either side of Sentinel Peak, crossed one after the other on the way from the Le Conte Glacier to the South Cascade Glacier. These are the highest useful sleeping spots on this part of the crest and the direct bases for Sentinel Peak and for Lizard Mountain, which stands just east of the col that carries the route across to the far side. accounts disagree on the elevations of both saddles by several hundred feet, with Lizard quoted anywhere from the high 6,000s to the mid 7,000s, so no numbers are recorded. A camp here is a fair-weather decision and nothing else: there is no shelter, no water, and the ground on both sides is glaciated, so retreating in cloud means downclimbing snow you only saw once in daylight. Most parties cross both in a day and sleep at a lake; the ones who stop are the ones who came to climb the peaks rather than pass them.", "permit": "Glacier Peak Wilderness, free self-issue permit. Camp on snow, rock or ice only. Pack out human waste, which matters here because the meltwater below feeds the lakes people are drinking from.", "type": "bivy", "water": "None running. Melt snow, or carry from the lakes below on whichever side you came from. In a late, thin season the snow at the saddles can be gone and then there is nothing at all."}, {"capacity": "Whatever the party can level. Rock rings, gravel benches and snow platforms for one party at a time, scattered along the divide. No toilet and no established sites of any kind.", "name": "Crest bivouacs above the South Cascade and Chickamin glaciers", "notes": "SAY IT PLAINLY: THESE ARE NOT SITES, THEY ARE WHEREVER A PARTY GETS TO. Elephant Head is the southernmost peak, standing on the divide above the lakes at the south end of the crest with big cliffs dropping east into the head of the west fork of Agnes Creek, between the ice on either side. It gets a handful of ascents in a decade and there is no established camp for it, so parties climbing it either work out from the lake basin below or level a spot on the divide and accept a dry, exposed night. The same is true of anyone caught out on the South Cascade side by weather or by a slower day than planned. The season is short and matters more here than anywhere else: July into August has the glaciers covered and the bivouac snow usable, while September brings open crevasses, bare ice and no water at all. Anyone planning a night on this ground should carry the fuel to melt snow and treat the whole thing as an unplanned shelter that happens to be foreseeable.", "permit": "Glacier Peak Wilderness, free self-issue permit. Camp on snow, rock or ice, never on the heather benches. Pack out human waste. No fires; there is nothing to burn and nothing that would recover.", "type": "bivy", "water": "Snowmelt only, and unreliable after midsummer. The last certain water on this stretch is the lakes below, and everything east of the divide is snow, ice and bare rock."}]'::jsonb WHERE id = 'wa_sentinel_peak_standard';
-- emergency.county corrected: the sentence opened 'Straddles the Snohomish/Chelan county line'
-- then went on to describe 'Skagit County' for the north approach and 'Snohomish County' for the
-- south approach -- internally contradictory (Skagit != Chelan), and Chelan County does not
-- border this part of the North Cascades crest. Corrected the opening clause to 'Skagit/
-- Snohomish', matching the rest of the same sentence and the row's own sheriffDispatch/
-- rangerStation fields (Skagit County Sheriff / Marblemount for the north side, Snohomish County
-- SAR / Darrington for the south side).
UPDATE routes SET emergency = '{"county": "Straddles the Skagit/Snohomish county line; the north approach (Cascade Pass) is in Skagit County and the south approach (Downey Creek) is in Snohomish County.", "nearestHospital": "North approach: PeaceHealth United General Medical Center, Sedro-Woolley, or Skagit Valley Hospital, Mount Vernon. South approach: Cascade Valley Hospital, Arlington.", "notes": "This is a genuinely remote objective reached only via multi-day glacier travel from either end of the Ptarmigan Traverse; there is no cell coverage and any rescue will take many hours to a day or more to reach the peak, so parties should be self-sufficient for crevasse rescue and basic first aid.", "rangerStation": "North Cascades NP Wilderness Information Center, Marblemount, (360) 854-7245 (permits/trip planning); Darrington Ranger District (Mt. Baker-Snoqualmie NF), (360) 436-1155, for the Suiattle/Downey Creek side.", "sheriffDispatch": "Skagit County Sheriff non-emergency (360) 336-9450, or North Cascades NP dispatch (360) 856-5700 ext. 515 / after-hours (360) 873-4590 ext. 37, for the north side; Snohomish County Volunteer Search & Rescue (425) 388-3328 for the south side."}'::jsonb WHERE id = 'wa_sentinel_peak_standard';
-- FLAGGED, not fixed: gain_ft (8500) and loss_ft (9200) both correctly match the sum of this
-- row's own itinerary day-by-day gainFt/lossFt figures, but a route whose waypoints show both
-- start and end at the same 3,600ft Cascade Pass Trailhead must have equal total gain and loss
-- -- it cannot legitimately net -700ft. Cannot tell from the data on file which day segment's
-- estimate is off; needs a human/topo pass rather than a guess at which number to change.

-- South Early Winter Spire, Southwest Rib (wa_sews_sw_rib):
-- itinerary.days[0].gainFt/lossFt corrected 2621 -> 2407 (and totalNote's 'roughly 2,600 ft'
-- to 'roughly 2,400 ft') to match the row's own already-corrected top-level gain_ft/loss_ft
-- (2407 = 7807-5400, per this row's OWN 2026-07-31 correction note fixing the trailhead
-- elevation specifically to agree with gain_ft=2407) -- the itinerary's day-level figures were
-- not updated in that same pass and were left at the pre-correction estimate.
UPDATE routes SET itinerary = '{"cal": "North Cascades Highway (SR-20) over Washington Pass usually opens by late May and closes with the first heavy snow (often November) \u2014 prime dry-rock season is June-September.", "days": [{"gainFt": 2407, "hours": 9.5, "lossFt": 2407, "miles": 6, "n": 1, "note": "Hike the Blue Lake trail then cut up to the base of SEWS''s southwest face, climb 7 pitches of low-5th to 5.8 rock to the summit, then downclimb part of the South Arete and rappel a short chimney back to the base.", "objective": "Climb the Southwest Rib and return to the Blue Lake trailhead", "packLb": 0, "schedule": [{"detail": "Popular route \u2014 early start beats other parties to the base.", "label": "Leave Blue Lake trailhead", "time": "6:00 AM"}, {"detail": "About 1 hr of steady uphill approach.", "label": "Reach base of Southwest Rib", "time": "7:00 AM"}, {"detail": "", "label": "Start climbing P1", "time": "7:15 AM"}, {"detail": "7 pitches of 5.6-5.8.", "label": "Top out, summit", "time": "11:30 AM"}, {"detail": "Downclimb part of the South Arete, then 2 rappels down the chimney.", "label": "Begin descent", "time": "12:15 PM"}, {"detail": "", "label": "Back at trailhead", "time": "4:00 PM"}], "title": "Car-to-car climb"}], "totalNote": "A long single day: about 9.5 hrs car-to-car with roughly 2,400 ft gain over 7 pitches."}'::jsonb WHERE id = 'wa_sews_sw_rib';

-- Sharkfin Tower, Southeast Ridge (wa_sharkfin_tower_southeast_ridge):
