UPDATE routes SET gain_ft = 4920, loss_ft = 4920 WHERE id = 'wa_sharkfin_tower_southeast_ridge';
-- bivy pruned 6->3, removing three entries (Sahale Glacier Camp, Pelton Basin, Johannesburg
-- Camp) that are reached from the separate Cascade Pass Trailhead at the end of Cascade River
-- Road, not from the Boston Basin climbers' trailhead this route's own approach uses (a
-- different, earlier pullout at mile 21.7). Kept Boston Basin lower camp and upper (high) camp
-- (both explicitly listed as the base for 'Sharkfin Tower' by name) and the informal snow/rock
-- bivouacs entry, which names 'the Sharkfin Col area' directly.
UPDATE routes SET bivy = '[{"capacity": "Zone quota is 6 parties per night for the whole Boston Basin cross-country zone, shared with the upper camp; maximum party size 12. Weekend permits go early.", "elev": 5300, "name": "Boston Basin lower camp", "notes": "The first hardened camp on the climbers'' trail up from the Cascade River Road pullout near mile 21.7, with a composting toilet. It is the usual base for Forbidden Peak''s West Ridge and North Ridge, Sharkfin Tower and the Torment-Forbidden traverse, and it stays snow-covered well into early summer. accounts differ on the exact elevation of the two Boston Basin camps \u2014 figures between roughly 5,300 and 5,700 ft are quoted for this one \u2014 so treat the number as approximate rather than a waypoint. Bear-resistant food storage is required.", "permit": "NPS wilderness permit required for any overnight stay, and for all Cascade River Road trailheads it must be collected IN PERSON at the Marblemount Wilderness Information Center. Roughly 60% of capacity is reservable in advance through Recreation.gov, about 40% held for walk-ups the day of or day before. These permits are NO LONGER FREE \u2014 older write-ups still say they are, which is out of date; confirm current pricing when you book.", "type": "camp", "water": "Meltwater creeks braid through the basin below the Quien Sabe and Boston glaciers and are normally reliable through the climbing season, though flow drops noticeably by late August and September in a light snow year."}, {"capacity": "Shares the same 6-party, 12-person Boston Basin zone quota as the lower camp; a handful of hardened tent platforms.", "elev": 6400, "name": "Boston Basin upper (high) camp", "notes": "Several hundred vertical feet above the lower camp and also served by a composting toilet, this shortens the morning to the Forbidden West Ridge couloir and to Sharkfin Tower considerably. There is a real tension in the published guidance worth knowing before you go: park zone rules describe camping on durable surfaces such as snow, rock or bare ground, while much of the practical guidance for Boston Basin says to use only the two established camps. In practice rangers direct climbers to the hardened sites, so plan on them and ask at Marblemount if you intend otherwise.", "permit": "Same NPS wilderness permit as the lower camp, collected in person at Marblemount; reservable portion on Recreation.gov, remainder held for walk-ups.", "type": "camp", "water": "Snowmelt runnels and glacier outflow are usually running nearby, but this is the less certain of the two camps late in the season \u2014 parties arriving in September should be ready to melt snow or carry it up from below."}, {"capacity": "Party-sized ledges and snow platforms only; no facilities, no toilet, and no reliable flat ground once the snow has melted out.", "name": "Informal snow and rock bivouacs above the basins", "notes": "Parties attempting the Torment-Forbidden traverse, a long day on Boston Peak, or a late finish on the Forbidden North Ridge sometimes end up bivouacking on snow or rock above the established camps, in the Sharkfin Col area, or in a notch on route. Treat these as unplanned or emergency shelter rather than as an itinerary: they are exposed, they have no water once the snow goes, and the surrounding terrain is glaciated. Human waste must be packed out, and food still needs bear-resistant storage.", "permit": "Still requires an NPS wilderness permit for the relevant cross-country zone, from Marblemount. Whether an unestablished high bivouac is acceptable in Boston Basin is genuinely CONTESTED \u2014 the general zone regulation allows camping on durable surfaces such as snow, rock or bare ground, while the site-specific guidance for Boston Basin says to use the two designated camps. Ask when you collect the permit rather than assuming.", "type": "bivy", "water": "Entirely snowmelt and therefore seasonal. Early in the summer there is running water almost everywhere; by late season the high ground can be bare rock with nothing running, so plan to carry water up or melt snow."}]'::jsonb WHERE id = 'wa_sharkfin_tower_southeast_ridge';

